function aggregateTransactions(csv) {
  const out = {};
  const seen = new Set();
  const lines = csv.split(/\r?\n/).slice(1);
  for (const raw of lines) {
    if (raw.trim() === '') continue;
    const f = raw.split(',').map(s => s.trim());
    if (f.length !== 5) continue;
    const [id, merchant, cur, amt, status] = f;
    if (!id || !merchant || !/^[A-Za-z]{3}$/.test(cur) || !/^\d+$/.test(amt)) continue;
    if (seen.has(id)) continue;
    seen.add(id);
    let sign;
    if (status === 'succeeded') sign = 1;
    else if (status === 'refunded') sign = -1;
    else continue;
    const key = merchant + '|' + cur.toUpperCase();
    out[key] = (out[key] || 0) + sign * Number(amt);
  }
  return out;
}

