import java.util.*;

class Solution {
  public Map<String, Long> aggregateTransactions(String csv) {
    Map<String, Long> out = new TreeMap<>();
    Set<String> seen = new HashSet<>();
    String[] lines = csv.split("\\r?\\n");
    for (int i = 1; i < lines.length; i++) {
      if (lines[i].trim().isEmpty()) continue;
      String[] f = lines[i].split(",", -1);
      if (f.length != 5) continue;
      for (int k = 0; k < 5; k++) f[k] = f[k].trim();
      String id = f[0], merchant = f[1], cur = f[2], amt = f[3], status = f[4];
      if (id.isEmpty() || merchant.isEmpty() || !cur.matches("[A-Za-z]{3}") || !amt.matches("\\d+")) continue;
      if (!seen.add(id)) continue;
      int sign;
      if (status.equals("succeeded")) sign = 1;
      else if (status.equals("refunded")) sign = -1;
      else continue;
      out.merge(merchant + "|" + cur.toUpperCase(), sign * Long.parseLong(amt), Long::sum);
    }
    return out;
  }
}

