function processRequests(ttl, requests) {
  const store = new Map(); // key -> { hash, at }
  const out = [];
  for (const line of requests) {
    const f = line.trim().split(/\s+/);
    if (f.length !== 3 || !/^-?\d+$/.test(f[0])) { out.push('invalid'); continue; }
    const t = Number(f[0]), key = f[1], hash = f[2];
    const e = store.get(key);
    if (!e || t >= e.at + ttl) {
      store.set(key, { hash, at: t });
      out.push('new');
    } else {
      out.push(e.hash === hash ? 'replay' : 'conflict');
    }
  }
  return out;
}

