import java.util.*;

class Solution {
  public List<String> processRequests(int ttl, String[] requests) {
    Map<String, String> hashes = new HashMap<>();
    Map<String, Long> at = new HashMap<>();
    List<String> out = new ArrayList<>();
    for (String line : requests) {
      String[] f = line.trim().split("\\s+");
      if (f.length != 3 || !f[0].matches("-?\\d+")) { out.add("invalid"); continue; }
      long t = Long.parseLong(f[0]);
      String key = f[1], hash = f[2];
      Long storedAt = at.get(key);
      if (storedAt == null || t >= storedAt + ttl) {
        hashes.put(key, hash);
        at.put(key, t);
        out.add("new");
      } else {
        out.add(hashes.get(key).equals(hash) ? "replay" : "conflict");
      }
    }
    return out;
  }
}

