function rateLimit(capacity, refillPerSec, requests) {
  const buckets = new Map(); // key -> { tokens, last }
  const out = [];
  for (const line of requests) {
    const [ts, key] = line.trim().split(/\s+/);
    const t = Number(ts);
    let b = buckets.get(key);
    if (!b) { b = { tokens: capacity, last: t }; buckets.set(key, b); }
    b.tokens = Math.min(capacity, b.tokens + (t - b.last) * refillPerSec);
    b.last = t;
    if (b.tokens >= 1) { b.tokens -= 1; out.push(true); }
    else out.push(false);
  }
  return out;
}

