import java.util.*;

class Solution {
  public List<Boolean> rateLimit(int capacity, double refillPerSec, String[] requests) {
    Map<String, double[]> buckets = new HashMap<>(); // {tokens, last}
    List<Boolean> out = new ArrayList<>();
    for (String line : requests) {
      String[] f = line.trim().split("\\s+");
      double t = Double.parseDouble(f[0]);
      double[] b = buckets.computeIfAbsent(f[1], k -> new double[]{capacity, t});
      b[0] = Math.min(capacity, b[0] + (t - b[1]) * refillPerSec);
      b[1] = t;
      if (b[0] >= 1) { b[0] -= 1; out.add(true); } else out.add(false);
    }
    return out;
  }
}

