function runLedger(commands) {
  const bal = new Map();
  const get = a => bal.get(a) || 0;
  const post = (debit, credit, amt) => { // two entries, always together
    bal.set(debit, get(debit) - amt);
    bal.set(credit, get(credit) + amt);
  };
  const isAmt = s => /^\d+$/.test(s) && Number(s) > 0;
  const out = [];
  for (const cmd of commands) {
    const f = cmd.trim().split(/\s+/);
    if (f[0] === 'DEPOSIT' && f.length === 3 && isAmt(f[2])) {
      post('world', f[1], Number(f[2])); out.push('OK');
    } else if (f[0] === 'TRANSFER' && f.length === 4 && isAmt(f[3]) && f[1] !== f[2]) {
      const amt = Number(f[3]);
      if (get(f[1]) < amt) out.push('INSUFFICIENT_FUNDS');
      else { post(f[1], f[2], amt); out.push('OK'); }
    } else if (f[0] === 'BALANCE' && f.length === 2) {
      out.push(String(get(f[1])));
    } else if (f[0] === 'CHECK' && f.length === 1) {
      let s = 0; for (const v of bal.values()) s += v;
      out.push(s === 0 ? 'BALANCED' : 'UNBALANCED');
    } else out.push('INVALID');
  }
  return out;
}

