import java.util.*;

class Solution {
  private final Map<String, Long> bal = new HashMap<>();

  private long get(String a) { return bal.getOrDefault(a, 0L); }

  private void post(String debit, String credit, long amt) {
    bal.put(debit, get(debit) - amt);
    bal.put(credit, get(credit) + amt);
  }

  private boolean isAmt(String s) { return s.matches("\\d+") && Long.parseLong(s) > 0; }

  public List<String> runLedger(String[] commands) {
    List<String> out = new ArrayList<>();
    for (String cmd : commands) {
      String[] f = cmd.trim().split("\\s+");
      if (f[0].equals("DEPOSIT") && f.length == 3 && isAmt(f[2])) {
        post("world", f[1], Long.parseLong(f[2])); out.add("OK");
      } else if (f[0].equals("TRANSFER") && f.length == 4 && isAmt(f[3]) && !f[1].equals(f[2])) {
        long amt = Long.parseLong(f[3]);
        if (get(f[1]) < amt) out.add("INSUFFICIENT_FUNDS");
        else { post(f[1], f[2], amt); out.add("OK"); }
      } else if (f[0].equals("BALANCE") && f.length == 2) {
        out.add(String.valueOf(get(f[1])));
      } else if (f[0].equals("CHECK") && f.length == 1) {
        long s = 0; for (long v : bal.values()) s += v;
        out.add(s == 0 ? "BALANCED" : "UNBALANCED");
      } else out.add("INVALID");
    }
    return out;
  }
}

