function retrySchedule(base, cap, maxAttempts, outcomes, rands) {
  const times = [];
  let t = 0;
  for (let i = 0; i < maxAttempts; i++) {
    times.push(t);
    if (outcomes[i] === true) return { times, delivered: true };
    if (i === maxAttempts - 1) break;
    const ceiling = Math.min(cap, base * Math.pow(2, i));
    t += Math.floor(rands[i] * ceiling);
  }
  return { times, delivered: false };
}

