import java.util.*;

class Solution {
  public long[] retrySchedule(long base, long cap, int maxAttempts, boolean[] outcomes, double[] rands) {
    List<Long> times = new ArrayList<>();
    long t = 0;
    boolean delivered = false;
    for (int i = 0; i < maxAttempts; i++) {
      times.add(t);
      if (i < outcomes.length && outcomes[i]) { delivered = true; break; }
      if (i == maxAttempts - 1) break;
      double ceiling = Math.min((double) cap, base * Math.pow(2, i));
      t += (long) Math.floor(rands[i] * ceiling);
    }
    long[] out = new long[times.size() + 1];
    for (int i = 0; i < times.size(); i++) out[i] = times.get(i);
    out[times.size()] = delivered ? 1 : 0;
    return out;
  }
}

