function formatAmount(amount, currency) {
  const cur = currency.toUpperCase();
  const zero = ['JPY', 'KRW', 'VND', 'CLP'];
  const three = ['BHD', 'KWD', 'JOD', 'OMR', 'TND'];
  const d = zero.includes(cur) ? 0 : three.includes(cur) ? 3 : 2;
  const neg = amount < 0;
  const digits = String(Math.abs(amount)).padStart(d + 1, '0');
  let major = digits.slice(0, digits.length - d);
  const minor = digits.slice(digits.length - d);
  major = major.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (neg ? '-' : '') + major + (d ? '.' + minor : '') + ' ' + cur;
}

