import java.util.*;

class Solution {
  public String formatAmount(long amount, String currency) {
    String cur = currency.toUpperCase();
    Set<String> zero = Set.of("JPY", "KRW", "VND", "CLP");
    Set<String> three = Set.of("BHD", "KWD", "JOD", "OMR", "TND");
    int d = zero.contains(cur) ? 0 : three.contains(cur) ? 3 : 2;
    boolean neg = amount < 0;
    String digits = Long.toString(Math.abs(amount));
    while (digits.length() < d + 1) digits = "0" + digits;
    String major = digits.substring(0, digits.length() - d);
    String minor = digits.substring(digits.length() - d);
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < major.length(); i++) {
      if (i > 0 && (major.length() - i) % 3 == 0) sb.append(',');
      sb.append(major.charAt(i));
    }
    return (neg ? "-" : "") + sb + (d > 0 ? "." + minor : "") + " " + cur;
  }
}
